CREATE SCHEMA IF NOT EXISTS episodio;

-- id is generated by the client (ULID/UUID); opened_at is the timestamp of the center, received_at the server's.
CREATE TABLE episodio.episode (
    id             UUID                     NOT NULL,
    patient_id     UUID                     NOT NULL,
    center_id      VARCHAR(64),
    doctor_subject UUID                     NOT NULL,
    status         VARCHAR(16)              NOT NULL,
    opened_at      TIMESTAMP WITH TIME ZONE NOT NULL,
    admitted_at    TIMESTAMP WITH TIME ZONE,
    received_at    TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT ck_episode_status CHECK (status IN ('WAITING', 'ADMITTED', 'IN_PROGRESS', 'COMPLETED'))
);

-- One row per independent clinical field, so last-writer-wins applies field by field.
CREATE TABLE episodio.episode_field (
    id         UUID                     NOT NULL,
    episode_id UUID                     NOT NULL,
    field_name VARCHAR(32)              NOT NULL,
    field_value VARCHAR(4000)           NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uq_episode_field UNIQUE (episode_id, field_name),
    CONSTRAINT fk_episode_field_episode FOREIGN KEY (episode_id) REFERENCES episodio.episode (id)
);

-- File bytes live in object storage; only metadata is here.
CREATE TABLE episodio.attachment (
    id           UUID                     NOT NULL,
    episode_id   UUID                     NOT NULL,
    file_name    VARCHAR(255)             NOT NULL,
    content_type VARCHAR(127)             NOT NULL,
    size_bytes   BIGINT                   NOT NULL,
    storage_key  VARCHAR(512)             NOT NULL,
    created_at   TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT fk_attachment_episode FOREIGN KEY (episode_id) REFERENCES episodio.episode (id)
);

-- Sync events already applied. Replaying an event id returns the stored outcome.
CREATE TABLE episodio.processed_event (
    event_id     UUID                     NOT NULL,
    message      VARCHAR(500)             NOT NULL,
    conflict     BOOLEAN                  NOT NULL,
    processed_at TIMESTAMP WITH TIME ZONE NOT NULL,
    PRIMARY KEY (event_id)
);
